functions.cms_write_mutex:
CREATE OR REPLACE FUNCTION public.cms_write_mutex()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(1398031696, 1);
    RETURN NULL;
END;
$function$

functions.guard_content_definition:
CREATE OR REPLACE FUNCTION public.guard_content_definition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
    closed boolean;
    owner_type uuid;
    owner_schema bigint;
BEGIN
    owner_type := CASE WHEN TG_OP='DELETE' THEN OLD.type_id ELSE NEW.type_id END;
    owner_schema := CASE WHEN TG_OP='DELETE' THEN OLD.schema_no ELSE NEW.schema_no END;
    IF TG_OP='UPDATE' AND (NEW.type_id,NEW.schema_no,NEW.field_id) IS DISTINCT FROM (OLD.type_id,OLD.schema_no,OLD.field_id) THEN
        RAISE EXCEPTION 'definition identity is immutable' USING ERRCODE = '23514';
    END IF;
    SELECT sealed INTO closed FROM public.content_schemas WHERE type_id=owner_type AND schema_no=owner_schema FOR UPDATE;
    IF closed THEN
        RAISE EXCEPTION 'sealed schema children are immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$

functions.guard_content_identity:
CREATE OR REPLACE FUNCTION public.guard_content_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'content identities cannot be deleted' USING ERRCODE = '23514';
    END IF;
    IF TG_TABLE_NAME = 'content_types' THEN
        IF (NEW.id,NEW.key,NEW.route_namespace,NEW.kind) IS DISTINCT FROM (OLD.id,OLD.key,OLD.route_namespace,OLD.kind) THEN
            RAISE EXCEPTION 'type identity is immutable' USING ERRCODE = '23514';
        END IF;
    ELSIF TG_TABLE_NAME = 'content_fields' THEN
        IF (NEW.type_id,NEW.field_id,NEW.key) IS DISTINCT FROM (OLD.type_id,OLD.field_id,OLD.key) THEN
            RAISE EXCEPTION 'field identity is immutable' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

functions.guard_content_item_identity:
CREATE OR REPLACE FUNCTION public.guard_content_item_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'content identities cannot be deleted' USING ERRCODE = '23514';
    END IF;
    IF TG_OP <> 'INSERT' THEN
        IF (NEW.id,NEW.type_id) IS DISTINCT FROM (OLD.id,OLD.type_id) THEN
            RAISE EXCEPTION 'item identity is immutable' USING ERRCODE = '23514';
        END IF;
        -- Version-only commands have no access to publication data.
        IF NEW.published_id IS NOT DISTINCT FROM OLD.published_id THEN
            RETURN NEW;
        END IF;
    END IF;
    IF NEW.published_id IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM public.content_publications p WHERE p.id=NEW.published_id AND p.item_id=NEW.id AND p.sealed) THEN
            RAISE EXCEPTION 'publication pointer requires sealed own revision' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

functions.guard_content_locale_relation:
CREATE OR REPLACE FUNCTION public.guard_content_locale_relation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP='UPDATE' AND (NEW.item_id,NEW.locale_code) IS NOT DISTINCT FROM (OLD.item_id,OLD.locale_code) THEN
        RETURN NEW;
    END IF;
    IF TG_TABLE_NAME='content_draft_locales' THEN
        IF EXISTS (SELECT 1 FROM public.content_draft_relations r WHERE r.item_id=OLD.item_id AND r.locale_scope=OLD.locale_code) THEN
            RAISE EXCEPTION 'draft locale_code has dependent relations' USING ERRCODE = '23503';
        END IF;
    ELSE
        IF EXISTS (SELECT 1 FROM public.content_publication_relations r WHERE r.publication_id=OLD.publication_id AND r.locale_scope=OLD.locale_code) THEN
            RAISE EXCEPTION 'publication locale_code has dependent relations' USING ERRCODE = '23503';
        END IF;
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$

functions.guard_content_publication:
CREATE OR REPLACE FUNCTION public.guard_content_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND OLD.sealed) THEN
        RAISE EXCEPTION 'publication is immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.id,NEW.item_id,NEW.type_id,NEW.schema_no,NEW.revision_no,NEW.shared_seq,NEW.shared_values,NEW.display_metadata,NEW.published_at)
        IS DISTINCT FROM (OLD.id,OLD.item_id,OLD.type_id,OLD.schema_no,OLD.revision_no,OLD.shared_seq,OLD.shared_values,OLD.display_metadata,OLD.published_at) THEN
        RAISE EXCEPTION 'only publication seal can change' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.content_schemas s WHERE s.type_id=NEW.type_id AND s.schema_no=NEW.schema_no AND s.sealed) THEN
        RAISE EXCEPTION 'publication requires sealed schema' USING ERRCODE = '23514';
    END IF;
    IF NEW.sealed AND NOT EXISTS (SELECT 1 FROM public.content_publication_locales l WHERE l.publication_id=NEW.id) THEN
        RAISE EXCEPTION 'publication requires at least one locale' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.guard_content_publication_child:
CREATE OR REPLACE FUNCTION public.guard_content_publication_child()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
    owner_id uuid;
    closed boolean;
BEGIN
    owner_id := CASE WHEN TG_OP='DELETE' THEN OLD.publication_id ELSE NEW.publication_id END;
    IF TG_OP='UPDATE' AND NEW.publication_id IS DISTINCT FROM OLD.publication_id THEN
        RAISE EXCEPTION 'publication child owner is immutable' USING ERRCODE = '23514';
    END IF;
    SELECT sealed INTO closed FROM public.content_publications WHERE id=owner_id FOR UPDATE;
    IF closed THEN
        RAISE EXCEPTION 'sealed publication children are immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$

functions.guard_content_relation:
CREATE OR REPLACE FUNCTION public.guard_content_relation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
    definition public.content_field_definitions%ROWTYPE;
BEGIN
    SELECT * INTO definition FROM public.content_field_definitions
        WHERE type_id=NEW.type_id AND schema_no=NEW.schema_no AND field_id=NEW.field_id;
    IF NOT FOUND OR definition.kind <> 'relation' OR definition.target_type_id IS DISTINCT FROM NEW.target_type_id
        OR (definition.scope='shared' AND NEW.locale_scope <> '')
        OR (definition.scope='localized' AND NEW.locale_scope = '') THEN
        RAISE EXCEPTION 'relation definition or scope mismatch' USING ERRCODE = '23514';
    END IF;
    IF NEW.locale_scope <> '' THEN
        IF TG_TABLE_NAME='content_draft_relations' THEN
            IF NOT EXISTS (SELECT 1 FROM public.content_draft_locales l WHERE l.item_id=NEW.item_id AND l.locale_code=NEW.locale_scope) THEN
                RAISE EXCEPTION 'localized relation needs own draft locale' USING ERRCODE = '23514';
            END IF;
        ELSE
            IF NOT EXISTS (SELECT 1 FROM public.content_publication_locales l WHERE l.publication_id=NEW.publication_id AND l.item_id=NEW.item_id AND l.locale_code=NEW.locale_scope) THEN
                RAISE EXCEPTION 'localized relation needs own publication locale' USING ERRCODE = '23514';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

functions.guard_content_route:
CREATE OR REPLACE FUNCTION public.guard_content_route()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'route reservations are permanent' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.content_types t WHERE t.id=NEW.type_id AND t.route_namespace=NEW.namespace) THEN
        RAISE EXCEPTION 'route namespace belongs to another type' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.guard_content_schema:
CREATE OR REPLACE FUNCTION public.guard_content_schema()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND OLD.sealed) THEN
        RAISE EXCEPTION 'sealed schema is immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.type_id, NEW.schema_no) IS DISTINCT FROM (OLD.type_id, OLD.schema_no) THEN
        RAISE EXCEPTION 'schema identity is immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.guard_language_generation:
CREATE OR REPLACE FUNCTION public.guard_language_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.generation <> 1 THEN
            RAISE EXCEPTION 'new locale generation must be one' USING ERRCODE = '23514';
        END IF;
    ELSE
        IF NEW.code IS DISTINCT FROM OLD.code THEN
            RAISE EXCEPTION 'locale identity is immutable' USING ERRCODE = '23514';
        END IF;
        NEW.generation := OLD.generation + CASE WHEN NEW.is_enabled IS DISTINCT FROM OLD.is_enabled THEN 1 ELSE 0 END;
    END IF;
    RETURN NEW;
END;
$function$

functions.guard_security_state:
CREATE OR REPLACE FUNCTION public.guard_security_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP IN ('DELETE', 'TRUNCATE') THEN
        RAISE EXCEPTION 'bootstrap marker cannot be removed' USING ERRCODE = '23514';
    END IF;
    IF OLD.bootstrap_completed AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'completed bootstrap marker is immutable' USING ERRCODE = '23514';
    END IF;
    IF OLD.site IS NOT NULL AND (NEW.site IS DISTINCT FROM OLD.site OR NEW.bootstrap_user_id IS DISTINCT FROM OLD.bootstrap_user_id) THEN
        RAISE EXCEPTION 'bootstrap installation binding is immutable' USING ERRCODE = '23514';
    END IF;
    IF NEW.bootstrap_completed AND NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id=NEW.bootstrap_user_id AND u.state='active' AND u.enrollment_completed_at IS NOT NULL) THEN
        RAISE EXCEPTION 'bootstrap completion requires active enrolled account' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.guard_site_child:
CREATE OR REPLACE FUNCTION public.guard_site_child()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE closed boolean; owner_id uuid;
BEGIN
 owner_id := CASE WHEN TG_OP='DELETE' THEN OLD.revision_id ELSE NEW.revision_id END;
 IF TG_OP='UPDATE' AND NEW.revision_id<>OLD.revision_id THEN
  RAISE EXCEPTION 'владелец снимка неизменяем' USING ERRCODE='23514';
 END IF;
 SELECT sealed INTO closed FROM public.site_revisions WHERE id=owner_id FOR UPDATE;
 IF closed IS DISTINCT FROM false THEN
  RAISE EXCEPTION 'опубликованный снимок неизменяем' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$function$

functions.guard_site_revision:
CREATE OR REPLACE FUNCTION public.guard_site_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.sealed THEN RAISE EXCEPTION 'новый снимок обязан быть черновиком' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.sealed OR (TG_OP='UPDATE' AND NEW.id<>OLD.id) THEN
  RAISE EXCEPTION 'опубликованный снимок неизменяем' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF NEW.sealed THEN
  -- Блокировка языков согласована с импортом и исключает отключение во время публикации.
  PERFORM public.lock_languages(ARRAY(SELECT code FROM public.languages
   WHERE code IN (NEW.default_language,NEW.fallback_language)
   OR code IN (SELECT language_code FROM public.site_revision_languages WHERE revision_id=NEW.id) ORDER BY code));
  IF NOT EXISTS(SELECT 1 FROM public.languages WHERE code=NEW.default_language AND is_enabled)
   OR NOT EXISTS(SELECT 1 FROM public.site_revision_languages WHERE revision_id=NEW.id AND language_code=NEW.fallback_language)
   OR EXISTS(SELECT 1 FROM public.site_revision_languages c JOIN public.languages l ON l.code=c.language_code
    WHERE c.revision_id=NEW.id AND (NOT l.is_enabled OR (c.name,c.native_name,c.direction) IS DISTINCT FROM (l.name,l.native_name,l.direction)))
   OR NOT EXISTS(SELECT 1 FROM public.site_revision_keys WHERE revision_id=NEW.id)
   OR EXISTS((SELECT message_key,placeholders FROM public.ui_message_keys EXCEPT SELECT message_key,placeholders FROM public.site_revision_keys WHERE revision_id=NEW.id)
    UNION ALL (SELECT message_key,placeholders FROM public.site_revision_keys WHERE revision_id=NEW.id EXCEPT SELECT message_key,placeholders FROM public.ui_message_keys))
   OR EXISTS(SELECT 1 FROM public.site_revision_languages c CROSS JOIN public.site_revision_keys k
    LEFT JOIN public.site_revision_messages m ON m.revision_id=c.revision_id AND m.language_code=c.language_code AND m.message_key=k.message_key
    WHERE c.revision_id=NEW.id AND k.revision_id=NEW.id AND (m.message_key IS NULL
     OR public.ui_placeholders(m.message_value)<>k.placeholders
     OR regexp_replace(m.message_value,'\{[a-z][a-z0-9_]*\}','','g') ~ '[{}]')) THEN
   RAISE EXCEPTION 'неполная или некорректная публикация UI' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END;
$function$

functions.guard_site_state:
CREATE OR REPLACE FUNCTION public.guard_site_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'состояние установки обязательно' USING ERRCODE='23514'; END IF;
 IF NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'неверная версия установки' USING ERRCODE='23514'; END IF;
 IF NEW.published_id IS NOT NULL THEN
  PERFORM 1 FROM public.site_revisions WHERE id=NEW.published_id AND sealed FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'публикация не закрыта' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.draft_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.site_revisions WHERE id=NEW.draft_id AND sealed) THEN
  RAISE EXCEPTION 'черновик уже закрыт' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$function$

functions.guard_user_activation:
CREATE OR REPLACE FUNCTION public.guard_user_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF NEW.state = 'active' AND NOT EXISTS (
        SELECT 1 FROM public.mfa_totp m WHERE m.user_id=NEW.id AND m.confirmed_at IS NOT NULL AND m.last_counter >= 0
    ) THEN
        RAISE EXCEPTION 'active account requires verified MFA enrollment' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'accounts cannot be deleted' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.require_content_publication_sealed:
CREATE OR REPLACE FUNCTION public.require_content_publication_sealed()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.content_publications p WHERE p.id=NEW.id AND p.sealed) THEN
        RAISE EXCEPTION 'publication must be sealed before commit' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$function$

functions.require_content_schema_sealed:
CREATE OR REPLACE FUNCTION public.require_content_schema_sealed()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.content_schemas s WHERE s.type_id=NEW.type_id AND s.schema_no=NEW.schema_no AND s.sealed) THEN
        RAISE EXCEPTION 'schema must be sealed before commit' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$function$
